import{z as p,x as d,o as n,c as m,q as o,j as r,D as e,d as l,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"128 维 Fbank 与 Conv2D 8× 下采样","description":"","frontmatter":{"title":"128 维 Fbank 与 Conv2D 8× 下采样","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-asr-fbank-downsample.md","filePath":"llm/qwen3-asr-fbank-downsample.md","lastUpdated":1791413859000}'),A={name:"llm/qwen3-asr-fbank-downsample.md"};function k(E,a,h,B,b,D){const t=d("Mermaid");return n(),m("div",null,[a[2]||(a[2]=o('<h1 id="_128-维-fbank-与-conv2d-8×-下采样" tabindex="-1">128 维 Fbank 与 Conv2D 8× 下采样 <a class="header-anchor" href="#_128-维-fbank-与-conv2d-8×-下采样" aria-label="Permalink to &quot;128 维 Fbank 与 Conv2D 8× 下采样&quot;">​</a></h1><div class="epigraph"><p>AuT 是一套注意力编码器–解码器（AED）式识别器：它对 128 维 Fbank 做 8 倍下采样，得到 12.5 Hz 的音频编码器。</p><footer>—— Qwen Team, Qwen3-ASR Technical Report, arXiv:2601.21337</footer></div><p>声学前端决定后面每一层看见的时间粒度。Qwen3-ASR 的 AuT 编码器不直接吃波形，而是先把 16 kHz 语音变成 128 维 Fbank，再经 Conv2D 在时间上做 <strong>8×</strong> 下采样。这一步把帧率从常见的 100 Hz 压到 12.5 Hz，才有后面动态窗口、分块卷积和语言模型侧的 token 预算。本篇只写这条前端：滤波器组维数为什么是 128，卷积为什么必须是时间上的 8 倍，而不把 Whisper 的 2× 茎、CTC 的帧分类器或后续 projector 一并展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原始波形在 16 kHz 下每秒 16000 个采样。若把采样点直接送进 Transformer，序列长度会把自注意力的二次代价打满，梯度也难以对准音素尺度的事件。经典做法是短时谱：窗内做傅里叶变换，沿频率轴用梅尔滤波器组积分，得到 Fbank。问题立刻变成两个整数超参：滤波器个数 \\(F\\)，以及时间轴还要再压多少倍。</p><p>Whisper（Radford 等，2022）用 80 维 log-mel，卷积茎只在时间上再做 2×，编码器大约工作在 50 Hz。这对纯 AED 识别够用，因为解码器自己有交叉注意力去对齐。Qwen3-ASR 走的是 LALM：AuT 的隐状态还要投影进 Qwen3，每一步音频 token 都占用语言模型的上下文槽。若仍停留在 50 Hz，一分钟语音就是 3000 个音频 token，长音频和流式批处理都会先被长度卡住。需要更狠的时间压缩，同时频率分辨率不能掉到把辅音、方言和歌声的频谱细节抹平。</p><h3 id="维数与下采样是同一笔预算" tabindex="-1">维数与下采样是同一笔预算 <a class="header-anchor" href="#维数与下采样是同一笔预算" aria-label="Permalink to &quot;维数与下采样是同一笔预算&quot;">​</a></h3><p>滤波器个数和下采样倍数不是独立旋钮。\\(F\\) 越大，Conv2D 在频率轴上可学的通道越宽，但卷积核的计算与显存按 \\(F\\) 涨；\\(8\\times\\) 越大，时间步越少，注意力更便宜，但过冲会把相邻音素叠进同一个 token。Qwen3-ASR 把这笔预算钉死为：<strong>128 维 Fbank，时间 8× Conv2D</strong>。报告图中把前端标成 FBank 100 Hz、AuT 隐状态 12.5 Hz，两者之比恰好是 8。本篇的问题就是：为什么是这两个数，以及卷积如何在二维谱图上同时动时间和频率。</p><p><span class="marginnote">Fbank 不是学习型 tokenizer。它是固定的梅尔滤波器组，把线性频率压成近似听觉的非线性刻度。可学习的是后面的 Conv2D 与 AuT，不是滤波器中心频率本身。把它写成「语音 codec」会把离散码本和连续谱特征混为一谈。</span></p><p><span class="marginnote">术语翻译：Fbank（filter bank）就是用一组「按人耳敏感度排列」的滤波器去粗化频谱——人耳对低频分得细、对高频分得粗，梅尔刻度描述的就是这种非线性；后面再取对数，是模拟响度的感知压缩。所以它更接近「给机器用的耳蜗」，而不是编解码器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="_128-维-fbank" tabindex="-1">128 维 Fbank <a class="header-anchor" href="#_128-维-fbank" aria-label="Permalink to &quot;128 维 Fbank&quot;">​</a></h3><p>对 16 kHz 波形做短时傅里叶变换，取功率谱，乘 128 个梅尔滤波器并取对数，得到</p> \\[\\mathbf{x}_t \\in \\mathbb{R}^{128},\\qquad t=1,\\ldots,T. \\]<p>\\(T\\) 是帧数。与 12.5 Hz 对齐的常见设定是：窗长约 25 ms、帧移 10 ms（160 个采样），于是 \\(T \\approx 100\\) 帧/秒，即图中的 100 Hz Fbank。若报告正文未逐项列出窗移，这一 10 ms 帧移应理解为与「100 Hz → 8× → 12.5 Hz」闭环一致的工程设定，而不是另造一套前端。128 比 Whisper 的 80 更宽：汉语方言、歌唱共振峰和噪声里的窄带干扰，多出来的滤波器提供更细的频带分割。代价是 Conv2D 第一层的输入通道（把谱图看成 1 通道、\\(128\\) 高、\\(T\\) 宽的特征图）更高。</p><p><span class="marginnote">数字实例：10 ms 帧移即每帧前进 160 个采样点（16 kHz × 0.01 s），25 ms 窗长盖住 400 个采样点；一分钟语音约 6000 帧，经 8× 只剩 750 个向量进入语言模型——前端把序列压短了 8 倍，语言模型的上下文槽才装得下长音频。</span></p><h3 id="conv2d-时间-8×" tabindex="-1">Conv2D 时间 8× <a class="header-anchor" href="#conv2d-时间-8×" aria-label="Permalink to &quot;Conv2D 时间 8×&quot;">​</a></h3><p>下采样用二维卷积，而不是只在时间上做 1D 步长。把 \\(\\mathbf{x}_{1:T}\\) 看成高 128、宽 \\(T\\) 的单通道图。时间 8× 最干净的实现是三层步长为 2 的卷积：\\(2^3=8\\)。第 \\(\\ell\\) 层时间长度</p> \\[T^{(\\ell)}=\\left\\lfloor\\frac{T^{(\\ell-1)}-1}{2}\\right\\rfloor+1 \\]<p>（对应核 \\(3\\times 3\\)、padding 1、stride 2 这一与 8× 配套的常见设定）。三层之后 \\(T^{(3)}\\approx T/8\\)。频率轴同样被步长切开，最后把剩余频带与通道维拼平，线性映到 AuT 的 \\(d_{\\mathrm{model}}\\)。于是编码器看到的不是 100 Hz 的谱帧，而是 12.5 Hz 的连续向量。</p>',20)),(n(),r(i,null,{default:e(()=>[s(t,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%2216%20kHz%20%E6%B3%A2%E5%BD%A2%22%5D%20--%3E%20FB%5B%22128%20%E7%BB%B4%20Fbank%22%5D%0A%20%20FB%20--%3E%20C1%5B%22Conv2D%20%E6%AD%A5%E9%95%BF%202%22%5D%0A%20%20C1%20--%3E%20C2%5B%22Conv2D%20%E6%AD%A5%E9%95%BF%202%22%5D%0A%20%20C2%20--%3E%20C3%5B%22Conv2D%20%E6%AD%A5%E9%95%BF%202%22%5D%0A%20%20C3%20--%3E%20AUT%5B%22AuT%20%E9%9A%90%E7%8A%B6%E6%80%81%2012.5%20Hz%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>8× 必须发生在进入自注意力之前。若先做全长度注意力再池化，二次项仍按 100 Hz 计，前端压缩就没有省到算力。Conv2D 把局部频谱纹理收成短序列，AuT 的层才在 12.5 Hz 上做内容混合。这与 CTC 系统常用的 4× 帧下采样不同：CTC 还要为每个输出步保留较密的对齐格；AED / LALM 把对齐交给注意力与语言模型，更敢压时间。</p><p><span class="marginnote">时间 8× 和频率方向的步长是两件事。频率被切开是为了让后续线性层吃到可管理的宽，不改变「每秒多少个音频 token」。评测 token 率时只看时间轴；把频率维的通道数误当成帧率，会把 12.5 Hz 算错。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Fbank 把谐波结构摊到梅尔轴上：元音的共振峰是宽峰，擦音是高频能量。128 个滤波器让这些峰不必挤在 80 个桶里。Conv2D 的局部核在相邻帧、相邻频带上做同一套权，等价于可学习的二维滤波器组：它能强化共振峰轨迹，也能抑制平稳噪声底。步长 2 是下采样，也是感受野扩张——三层之后，一个输出向量大约看见 8 帧 Fbank，也就是与 12.5 Hz 对齐的常见设定下约 80 ms 的声学上下文。这 80 ms 正好是后文 ForcedAligner 把时间戳离散成索引的格子。</p><h3 id="为何不是-2×-或-16×" tabindex="-1">为何不是 2× 或 16× <a class="header-anchor" href="#为何不是-2×-或-16×" aria-label="Permalink to &quot;为何不是 2× 或 16×&quot;">​</a></h3><p>2×（Whisper 茎）把编码器留在 50 Hz，LALM 的上下文会翻四倍，动态窗口的 8 s 也会变成四倍 token，FlashAttention 的块更长。16× 则把格子推到 160 ms，辅音丛、短助词和中英混码的边界更容易糊进同一个向量，LID 和强制对齐都会变粗。8× 落在「语言模型能吞下的长度」和「对齐还分得清字」之间。它不是从 CTC 格子推出来的，而是从 LALM 的 token 预算反推回来的。</p><p>卷积的平移等变性还解释了为什么前端能和流式切块兼容：同一套核扫每一段 100 帧的谱图，不依赖全句长度。全序列一次性卷积会在块边界制造未来帧泄露；把 8× 做成局部运算，才给分块 Conv2D 留下因果化的口子。机制上，8× 既是压缩，也是把时间轴切成可流式的原子。</p><p>把三档下采样倍数各自的后果排在一起，就能看清 8× 落在哪——这张图回答的是「为什么不是 2× 或 16×」：</p>',8)),(n(),r(i,null,{default:e(()=>[s(t,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20LR%0A%20%20F0%5B%22100%20Hz%20Fbank%22%5D%20--%3E%20A%5B%222%20%E5%80%8D%E5%88%B0%2050%20Hz%22%5D%0A%20%20F0%20--%3E%20B%5B%228%20%E5%80%8D%E5%88%B0%2012.5%20Hz%22%5D%0A%20%20F0%20--%3E%20Cc%5B%2216%20%E5%80%8D%E5%88%B0%206.25%20Hz%22%5D%0A%20%20A%20--%3E%20X%5B%22%E4%B8%80%E5%88%86%E9%92%9F%203000%20token%20LLM%20%E4%B8%8A%E4%B8%8B%E6%96%87%E5%90%83%E7%B4%A7%22%5D%0A%20%20B%20--%3E%20Y%5B%22%E4%B8%80%E5%88%86%E9%92%9F%20750%20token%20%E5%AF%B9%E9%BD%90%E4%BB%8D%E8%83%BD%E5%88%86%E6%B8%85%E5%AD%97%22%5D%0A%20%20Cc%20--%3E%20Z%5B%22%E4%B8%80%E5%88%86%E9%92%9F%20375%20token%20%E8%BE%85%E9%9F%B3%E4%B8%9B%E7%B3%8A%E8%BF%9B%E5%90%8C%E4%B8%80%E6%A0%BC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>128 维 Fbank 仍是手工听觉近似，不是数据里学出的滤波器。极低采样率、电话带宽或已经是编解码器 Mel 的输入，需要重算滤波器，不能假设 128 个桶的中心频率仍对齐。8× 卷积对窗移敏感：若把 10 ms 帧移改成 20 ms 却仍做 8×，token 率会掉到 6.25 Hz，与训练时的 12.5 Hz 错位，语言模型侧的位置几何会坏。</p><p><span class="marginnote">不要用「参数量」解释 128 与 8。1.7B 与 0.6B 共用同一套 Fbank 维数和下采样倍数，差的是 AuT 隐层宽度（1024 对 896）和 Qwen3 解码器大小。前端整数是家族常数，不是随模型尺度浮动的超参。</span></p><p><span class="marginnote">常见误区：处理 8 kHz 电话音频时，只把它重采样到 16 kHz 并不能找回信息——8 kHz 以上的频带在录制时就已经是空的，128 个梅尔滤波器里高频那一段会恒为零。问题不在维数对不齐，而在于高频辅音（如 /s/、/ts/ 的能量区）已永久丢失，识别上限天然更低。</span></p><p>边界还在于：Conv2D 8× 之后，时间分辨率的上限已经钉死。后续注意力窗口再大，也恢复不出比 80 ms 更细的帧。要字级时间戳，不能指望解码器「再看一眼波形」，而要另建 ForcedAligner 在 12.5 Hz 格子上填槽。把 ASR 解码器的自回归步误当成时间轴，是把语言离散和声学离散混用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Qwen3-ASR 的声学前端是 128 维 Fbank，再经 Conv2D 在时间上 8× 下采样。</li><li>与 12.5 Hz 对齐的常见设定：16 kHz、约 10 ms 帧移 → 100 Hz Fbank，除以 8 得到 12.5 Hz。</li><li>8× 通常由三层时间步长 2 的卷积实现，\\(2^3=8\\)，把编码器序列压到 LALM 可承受的长度。</li><li>比 Whisper 的 80 维 / 2× 更宽、更狠：频率多留细节，时间多让出上下文槽。</li><li>一个下采样后的向量大约对应 80 ms，这是后续 token 率与时间戳格子的共同原点。</li><li>改帧移或改倍数都会破坏 12.5 Hz 闭环，不能只改一端。</li><li>出处：Qwen Team, <em>Qwen3-ASR Technical Report</em>, arXiv:2601.21337；对照 Radford 等，Whisper，2022；AED 见 Chan 等，Listen, Attend and Spell；CTC 为帧级对齐的对照路径。</li></ul>',7))])}const C=p(A,[["render",k]]);export{T as __pageData,C as default};
